/**
 * Bounded focus/overlay normalization before offline-kill Settings open (harness-only).
 * Aligns activeElement away from a focused gear when the passing Settings baseline shows BODY.
 */
async function normalizeOfflineKillSettingsOpenPrecondition(pg, _testInfo) {
    const collect = async () => {
        try {
            return await pg.evaluate(() => {
                const norm = (s) => (typeof s === 'string' ? s.trim().slice(0, 200) : '');
                const rectVisible = (el) => {
                    if (!(el instanceof Element)) return false;
                    const r = el.getBoundingClientRect();
                    const st = window.getComputedStyle(el);
                    return (
                        r.width > 0 &&
                        r.height > 0 &&
                        st.visibility !== 'hidden' &&
                        st.display !== 'none' &&
                        Number(st.opacity || '1') > 0
                    );
                };
                const overlaySelectors =
                    '[role="dialog"], [aria-modal="true"], [data-testid="session-modal"], [data-testid="command-palette"]';
                const dialogModalOverlayCandidates = Array.from(document.querySelectorAll(overlaySelectors))
                    .slice(0, 16)
                    .map((el) => ({
                        tag: String(el.tagName || ''),
                        dataTestId: el.getAttribute('data-testid') || '',
                        role: el.getAttribute('role') || '',
                        ariaModal: el.getAttribute('aria-modal') || '',
                        text: norm(el.textContent || '').slice(0, 160),
                        visible: rectVisible(el),
                    }));
                const ae = document.activeElement;
                return {
                    url: location.href,
                    viewport: { width: window.innerWidth, height: window.innerHeight },
                    drawerCount: document.querySelectorAll('[data-testid="settings-drawer"]').length,
                    openDrawerCount: document.querySelectorAll('[data-testid="settings-drawer"][data-state="open"]').length,
                    settingsOpenBtnCount: document.querySelectorAll('[data-testid="settings-open-btn"]').length,
                    dialogModalOverlayCandidates,
                    activeElement:
                        ae instanceof Element
                            ? {
                                  tag: ae.tagName,
                                  dataTestId: ae.getAttribute('data-testid') || '',
                                  ariaLabel: norm(ae.getAttribute('aria-label') || ''),
                              }
                            : null,
                };
            });
        } catch (err) {
            return { collectError: err && err.message ? String(err.message) : String(err) };
        }
    };
    const before = await collect();
    await attachJsonSnapshot('offline-kill-open-settings-precondition-before.json', {
        classification: 'offline-kill-settings-open-precondition-before',
        ...offlineKillBudgetSnapshot(),
        ...before,
    });

    await pg.keyboard.press('Escape').catch(() => {});
    await pg.waitForTimeout(120).catch(() => {});
    await dismissBlockingOverlaysNoBackdrop({ budgetMs: 4000 }).catch(() => {});
    await pg
        .evaluate(() => {
            const ae = document.activeElement;
            if (!(ae instanceof Element)) return;
            if (ae.getAttribute('data-testid') === 'settings-open-btn') {
                ae.blur();
                if (document.body instanceof HTMLElement) {
                    document.body.focus();
                }
            }
        })
        .catch(() => {});
    await pg
        .evaluate(
            () =>
                new Promise((resolve) => {
                    requestAnimationFrame(() => {
                        requestAnimationFrame(() => resolve(null));
                    });
                }),
        )
        .catch(() => {});
    await pg.waitForTimeout(150).catch(() => {});

    const after = await collect();
    await attachJsonSnapshot('offline-kill-open-settings-precondition-after.json', {
        classification: 'offline-kill-settings-open-precondition-after',
        ...offlineKillBudgetSnapshot(),
        ...after,
        noOpenDrawerPreClick:
            !after.collectError && Number(after.drawerCount) === 0 && Number(after.openDrawerCount) === 0,
    });
}

