function buildOfflineKillRuntimeStateSummary(snap) {
    if (!snap || typeof snap !== 'object') return 'missing';
    if (snap.collectError) return `collect-error:${String(snap.collectError).slice(0, 200)}`;
    const ls = Array.isArray(snap.localStorageMatchRows) ? snap.localStorageMatchRows.length : -1;
    const ss = Array.isArray(snap.sessionStorageMatchRows) ? snap.sessionStorageMatchRows.length : -1;
    const wk = Array.isArray(snap.windowKeyMatches) ? snap.windowKeyMatches.length : -1;
    const prov = snap.settingsProviderSelectValue != null ? String(snap.settingsProviderSelectValue).slice(0, 48) : 'n/a';
    const dc = snap.drawerCount != null ? snap.drawerCount : '?';
    const odc = snap.openDrawerCount != null ? snap.openDrawerCount : '?';
