        snap.activeElement && snap.activeElement.dataTestId
            ? snap.activeElement.dataTestId
            : snap.activeElement && snap.activeElement.tag
              ? String(snap.activeElement.tag)
              : '';
    return `ls=${ls}|ss=${ss}|wk=${wk}|drawer=${dc}/${odc}|provider=${prov}|ae=${String(ae).slice(0, 48)}`;
}

